CREATE TABLE IF NOT EXISTS customer_orders (id TEXT PRIMARY KEY, request_key TEXT NOT NULL UNIQUE, customer TEXT NOT NULL, phone TEXT NOT NULL, district TEXT NOT NULL, area TEXT NOT NULL, address TEXT NOT NULL, items TEXT NOT NULL, subtotal_minor INTEGER NOT NULL, delivery_minor INTEGER NOT NULL, total_minor INTEGER NOT NULL, currency TEXT NOT NULL DEFAULT 'BDT', status TEXT NOT NULL DEFAULT 'pending', courier TEXT NOT NULL, tracking TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS customer_orders_phone_time ON customer_orders(phone,created_at);
